<template>
  <div :id="'PieCharts' + id" :style="{ width: '100%', height: '100%' }"></div>
</template>

<script>
import echarts from '@/views/bigScreen/com/echarts'; 
import { echartsMixin } from '../../com/echartsMixin';

export default {
  name: 'PieCharts',
  mixins: [echartsMixin],
  props: {
    echartsData: {
      type: Array,
      default: () => [],
    },
    
    id: {
      type: String,
      default: '',
    },
  },
  data() {
    return {
      myEchart: null,
    };
  },
  methods: {
    initChart() {
      const chartDom = document.getElementById('PieCharts' + this.id);
      if (!chartDom) return;

      this.myEchart = echarts.init(chartDom);
      let total = 0
      if(this.echartsData&&this.echartsData.length>0){
        total = this.echartsData.reduce((a, b) => a + b.value, 0);
      }

      const option = {
        tooltip: {
          trigger: 'item',
          backgroundColor:'#073371c7',
          borderWidth: 1,
          borderColor:'#0085ff8f',
          textStyle:{
              color:'#fff'
          }
        },
        graphic: [{
          type: 'image',
          left: 'center',
          top: 'center',
          z: -10,
          bounding: 'all',
          rotation: 0, //旋转
          scale: [1.0, 1.0], //缩放
          style: {
            image: 'data:image/png;base64,',
            opacity: 1,
            width: 133 * 1.1 ,
            height: 133 * 1.1,
          },
      },],
        series: [
          {
            name: '',
            type: 'pie',
            radius: ['55%', '68%'],
            center: ['50%', '50%'],
            padAngle:5,
            label:{
              show: true,
              position: "outside",
              formatter: function (params) {
                 return "{a| " + params.name + "}\n{b| " + params.percent + "%}";
              },
              rich: {
                a: {
                  with: 200,
                  fontSize: 16,
                  color: '#ffffffa6',
                  padding: [0, 0, 15, -20],
                },
                b: {
                  fontSize: 18,
                  color: '#ffffff',
                },
              }
            },
            labelLine: {
              show: true,
              length: 10,
              length2: 30,
              align: 'right',
            },
            data: this.echartsData,
          },
        ],
      };

      this.myEchart.setOption(option);
    },
  },
};
</script>